@if($order->status === 'pending_payment' && $paymentDeadline)<script>document.addEventListener('DOMContentLoaded',()=>{const el=document.querySelector('[data-payment-countdown]');if(!el)return;const tick=()=>{const seconds=Math.max(0,Math.floor((new Date(el.dataset.expiresAt)-Date.now())/1000));el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0)location.reload()};tick();setInterval(tick,1000)});</script>@endif
